func (s *Server) adminOrganizations(w http.ResponseWriter, r *http.Request) {
	if err := requireAdmin(principal(r), false); err != nil {
		s.serviceError(w, r, err)
		return
	}
	rows, err := s.DB.Query(r.Context(), `SELECT id,COALESCE(parent_id::text,''),name,code,org_type,active,created_at FROM organizations ORDER BY code`)
	if err != nil {
		s.serviceError(w, r, err)
		return
	}
	defer rows.Close()
	items := []map[string]any{}
	for rows.Next() {
		var id, parent, name, code, typ string
		var active bool
		var created time.Time
		if err = rows.Scan(&id, &parent, &name, &code, &typ, &active, &created); err != nil {
			s.serviceError(w, r, err)
			return
		}
		items = append(items, map[string]any{"id": id, "parentId": parent, "name": name, "code": code, "type": typ, "active": active, "createdAt": created})
	}
	httpx.JSON(w, 200, map[string]any{"items": items})
}
func (s *Server) createOrganization(w http.ResponseWriter, r *http.Request) {
	p := principal(r)
	if err := requireAdmin(p, true); err != nil {
		s.serviceError(w, r, err)
		return
	}
	var in struct {
		ParentID string `json:"parentId"`
		Name     string `json:"name"`
		Code     string `json:"code"`
		Type     string `json:"type"`
	}
	if !httpx.DecodeJSON(w, r, &in) {
		return
	}
	if in.Name == "" || in.Code == "" {
		s.serviceError(w, r, errors.New("name and code are required"))
		return
	}
	if in.Type == "" {
		in.Type = "DEPARTMENT"
	}
	id := ids.New()
	_, err := s.DB.Exec(r.Context(), `INSERT INTO organizations(id,parent_id,name,code,org_type) VALUES($1,$2,$3,$4,$5)`, id, nullAdmin(in.ParentID), in.Name, strings.ToUpper(in.Code), strings.ToUpper(in.Type))
	if err != nil {
		s.serviceError(w, r, err)
		return
	}
	s.Audit.Record(r.Context(), audit.Event{ActorID: p.UserID, ActorName: p.Username, Channel: "ADMIN", Action: "ORGANIZATION_CREATE", Resource: "organization", ResourceID: id, After: in, IP: httpx.ClientIP(r), RequestID: httpx.RequestID(r.Context()), UserAgent: r.UserAgent()})
	httpx.JSON(w, 201, map[string]any{"id": id})
}

func (s *Server) adminAudit(w http.ResponseWriter, r *http.Request) {
	if err := requireAdmin(principal(r), false); err != nil {
		s.serviceError(w, r, err)
		return
	}
	limit := httpx.IntQuery(r, "limit", 100, 1, 500)
	channel := strings.ToUpper(strings.TrimSpace(r.URL.Query().Get("channel")))
	resource := strings.TrimSpace(r.URL.Query().Get("resource"))
	action := strings.ToUpper(strings.TrimSpace(r.URL.Query().Get("action")))
	query := strings.TrimSpace(r.URL.Query().Get("q"))
	rows, err := s.DB.Query(r.Context(), `SELECT id,COALESCE(actor_id::text,''),COALESCE(actor_name,''),channel,action,resource,COALESCE(resource_id,''),before_data,after_data,metadata,COALESCE(ip::text,''),COALESCE(request_id,''),COALESCE(user_agent,''),occurred_at
		FROM audit_logs
		WHERE ($1='' OR channel=$1)
		  AND ($2='' OR resource=$2)
		  AND ($3='' OR action=$3)
		  AND ($4='' OR COALESCE(actor_name,'') ILIKE $4 ESCAPE '\' OR action ILIKE $4 ESCAPE '\' OR resource ILIKE $4 ESCAPE '\' OR COALESCE(resource_id,'') ILIKE $4 ESCAPE '\' OR COALESCE(request_id,'') ILIKE $4 ESCAPE '\')
		ORDER BY occurred_at DESC LIMIT $5`, channel, resource, action, crm.SearchPattern(query), limit)
	if err != nil {
		s.serviceError(w, r, err)
		return
	}
	defer rows.Close()
	items := []map[string]any{}
	for rows.Next() {
		var row auditRow
		if err = rows.Scan(&row.id, &row.actorID, &row.actor, &row.channel, &row.action, &row.resource, &row.resourceID, &row.before, &row.after, &row.metadata, &row.ip, &row.requestID, &row.userAgent, &row.occurredAt); err != nil {
			s.serviceError(w, r, err)
			return
		}
		items = append(items, auditItem(row))
	}
	httpx.JSON(w, 200, map[string]any{"items": items})
}

// auditRow is one audit_logs row as adminAudit scans it; the jsonb columns
// stay raw bytes until auditItem decodes them.
type auditRow struct {
	id, actorID, actor, channel, action, resource, resourceID, ip, requestID, userAgent string
	before, after, metadata                                                             []byte
	occurredAt                                                                          time.Time
}

// auditItem turns a scanned row into the API item. The three jsonb columns
// are decoded independently: a NULL column or bytes that fail to decode are
// exported as null rather than failing the whole listing.
func auditItem(row auditRow) map[string]any {
	var before, after, metadata any
	_ = json.Unmarshal(row.before, &before)
	_ = json.Unmarshal(row.after, &after)
	_ = json.Unmarshal(row.metadata, &metadata)
	return map[string]any{"id": row.id, "actorId": row.actorID, "actor": row.actor, "channel": row.channel, "action": row.action, "resource": row.resource, "resourceId": row.resourceID, "before": before, "after": after, "metadata": metadata, "ip": row.ip, "requestId": row.requestID, "userAgent": row.userAgent, "occurredAt": row.occurredAt}
}

