func diagnosticReadiness(checks []adminDiagnosticCheck) int {
	required, healthy := 0, 0
	for _, check := range checks {
		if !check.Required {
			continue
		}
		required++
		if check.Status == "HEALTHY" {
			healthy++
		}
	}
	if required == 0 {
		return 100
	}
	return healthy * 100 / required
}

